contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(other != address(this), "other must differ from test contract");
        require(address(this).balance >= 1, "not enough balance");

        c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.balances(other); if (__ESBMC_reverted()) return;

        uint256 beforeOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 beforeSelf = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 afterOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 afterSelf = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(afterSelf == 0 && afterOther == beforeOther);
    }

    receive() external payable {}
}

