    function _run(address other) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(other != address(this));
        vm.assume(address(this).balance >= 1);
        try c.balances(address(this)) {} catch { return; }
        try c.balances(other) {} catch { return; }
        uint256 beforeOther;
        try c.balances(other) returns (uint256 __r) { beforeOther = __r; } catch { return; }
        uint256 beforeSelf;
        try c.balances(address(this)) returns (uint256 __r) { beforeSelf = __r; } catch { return; }
        try c.withdraw() {} catch { return; }
